SELECT 'pantanal' region,'temperature' variable,time,sum(air_temperature_at_10_meters_celsius*cos(radians(latitude)))/sum(cos(radians(latitude))) value,count(*) cells,min(latitude) min_lat,max(latitude) max_lat FROM `earth-trend-data`.trusted.tb_merra2_t10m WHERE latitude BETWEEN -22 AND -16 AND longitude BETWEEN -60 AND -54 AND air_temperature_at_10_meters_celsius IS NOT NULL AND NOT isnan(air_temperature_at_10_meters_celsius) AND abs(air_temperature_at_10_meters_celsius)<1e20 GROUP BY time
UNION ALL
SELECT 'pantanal' region,'rainfall' variable,time,sum(monthly_precipitation_millimeters*cos(radians(latitude))*valid_area_fraction)/sum(cos(radians(latitude))*valid_area_fraction) value,count(*) cells,min(latitude) min_lat,max(latitude) max_lat FROM `earth-trend-data`.trusted.tb_gpm_imerg_precipitation WHERE latitude BETWEEN -22 AND -16 AND longitude BETWEEN -60 AND -54 AND monthly_precipitation_millimeters IS NOT NULL AND NOT isnan(monthly_precipitation_millimeters) AND abs(monthly_precipitation_millimeters)<1e20 AND valid_area_fraction>0 AND valid_area_fraction<=1 AND monthly_precipitation_millimeters>=0 GROUP BY time
UNION ALL
SELECT 'pantanal' region,'water_storage' variable,time,sum(surface_mass_anomaly_millimeters_water_equivalent*cos(radians(latitude))*valid_area_fraction)/sum(cos(radians(latitude))*valid_area_fraction) value,count(*) cells,min(latitude) min_lat,max(latitude) max_lat FROM `earth-trend-data`.trusted.tb_grace_jpl_mass_anomaly WHERE latitude BETWEEN -22 AND -16 AND longitude BETWEEN -60 AND -54 AND surface_mass_anomaly_millimeters_water_equivalent IS NOT NULL AND NOT isnan(surface_mass_anomaly_millimeters_water_equivalent) AND abs(surface_mass_anomaly_millimeters_water_equivalent)<1e20 AND valid_area_fraction>0 AND valid_area_fraction<=1 GROUP BY time
UNION ALL
